#define FONT_COUNT ((int)(sizeof font_table / sizeof font_table[0]))

const PSGlyph *ps_font_glyph(uint32_t cp)
{
    static PSGlyph g = {5, 12, 0};
    int lo = 0, hi = FONT_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (font_table[mid].cp == cp) { g.rows = font_table[mid].rows; return &g; }
        if (font_table[mid].cp < cp) lo = mid + 1; else hi = mid - 1;
    }
    return NULL;
}
